// Independent verification model, written from scratch.
// Mirrors test18.cpp exactly but with std::map standing in for SortedMap.
#include <cstdlib>
#include <iostream>
#include <map>
#include <string>
#include <tuple>
#include <vector>

typedef std::tuple<int,int> Key;

int main(int argc, char* argv[]) {
    int n = 18;
    if (argc > 1) n = std::atoi(argv[1]);

    std::map<Key, std::string> m;
    for (int i = 0; i < n; i++)
        m[std::make_tuple(i, i*2)] = "value_" + std::to_string(i);

    std::cout << m.size() << "\n";

    Key k1 = std::make_tuple(3,6);
    Key k2 = std::make_tuple(5,10);

    std::cout << (m.count(k1) ? 1 : 0) << "\n";
    std::cout << (m.count(k2) ? 1 : 0) << "\n";
    std::cout << m[k1] << "\n";          // inserts "" if absent
    m[k1] = "modified";
    std::cout << m[k1] << "\n";

    std::vector<Key> keys; std::vector<std::string> vals;
    for (auto& p : m) { keys.push_back(p.first); vals.push_back(p.second); }
    std::cout << keys.size() << "\n";
    std::cout << vals.size() << "\n";

    for (int i = 0; i < 4; i++) m.erase(std::make_tuple(i, i*2));
    std::cout << m.size() << "\n";

    auto it = m.find(std::make_tuple(6,12));
    if (it != m.end()) std::cout << it->second << "\n";

    auto lb = m.lower_bound(std::make_tuple(7,14));
    if (lb != m.end()) std::cout << std::get<0>(lb->first) << "\n";

    auto ub = m.upper_bound(std::make_tuple(7,14));
    if (ub != m.end()) std::cout << std::get<0>(ub->first) << "\n";

    std::map<Key, std::string> m2;
    for (int i = 0; i < n/2; i++)
        m2[std::make_tuple(i+10, (i+10)*2)] = "other_" + std::to_string(i);

    for (auto& p : m2) m[p.first] = p.second;   // update(): overwrite

    std::cout << m.size() << "\n";
    std::cout << (m.count(std::make_tuple(12,24)) ? 1 : 0) << "\n";

    auto r = m.equal_range(std::make_tuple(8,16));
    int count = 0;
    for (auto i2 = r.first; i2 != r.second; ++i2) count++;
    std::cout << count << "\n";

    auto g = m.find(std::make_tuple(100,200));
    std::cout << (g == m.end() ? std::string("default") : g->second) << "\n";

    m.clear();
    std::cout << m.size() << "\n";
    std::cout << (m.empty() ? 1 : 0) << "\n";
    return 0;
}
EOF
