use std::collections::BTreeMap;

fn c_atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0usize;
    while i < b.len() && (b[i] == b' ' || (b[i] >= 0x09 && b[i] <= 0x0d)) { i += 1; }
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') { neg = b[i] == b'-'; i += 1; }
    let mut acc: i64 = 0;
    let mut sat = false;
    while i < b.len() && b[i].is_ascii_digit() {
        if !sat {
            acc = acc * 10 + (b[i] - b'0') as i64;
            if acc > i64::MAX / 16 { sat = true; }
        }
        i += 1;
    }
    // glibc atoi = (int)strtol(...); saturate to long then truncate.
    let v: i64 = if sat { if neg { i64::MIN } else { i64::MAX } } else if neg { -acc } else { acc };
    v as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: i32 = if args.len() > 1 { c_atoi(&args[1]) } else { 18 };

    let mut m: BTreeMap<(i32, i32), String> = BTreeMap::new();
    let mut i = 0i32;
    while i < n { m.insert((i, i * 2), format!("value_{}", i)); i += 1; }

    let mut out = String::new();
    out.push_str(&format!("{}\n", m.len()));
    let k1 = (3, 6);
    let k2 = (5, 10);
    out.push_str(&format!("{}\n", if m.contains_key(&k1) { 1 } else { 0 }));
    out.push_str(&format!("{}\n", if m.contains_key(&k2) { 1 } else { 0 }));
    let e = m.entry(k1).or_insert_with(String::new);
    out.push_str(&format!("{}\n", e));
    *m.get_mut(&k1).unwrap() = "modified".to_string();
    out.push_str(&format!("{}\n", m[&k1]));

    let keys: Vec<(i32, i32)> = m.keys().cloned().collect();
    let vals: Vec<String> = m.values().cloned().collect();
    out.push_str(&format!("{}\n", keys.len()));
    out.push_str(&format!("{}\n", vals.len()));

    for i in 0..4 { m.remove(&(i, i * 2)); }
    out.push_str(&format!("{}\n", m.len()));

    if let Some(v) = m.get(&(6, 12)) { out.push_str(&format!("{}\n", v)); }
    if let Some((k, _)) = m.range((7, 14)..).next() { out.push_str(&format!("{}\n", k.0)); }
    if let Some((k, _)) = m.range((7, 15)..).next() { out.push_str(&format!("{}\n", k.0)); }

    let mut m2: BTreeMap<(i32, i32), String> = BTreeMap::new();
    let mut i = 0i32;
    while i < n / 2 { m2.insert((i + 10, (i + 10) * 2), format!("other_{}", i)); i += 1; }
    for (k, v) in m2 { m.insert(k, v); }

    out.push_str(&format!("{}\n", m.len()));
    out.push_str(&format!("{}\n", if m.contains_key(&(12, 24)) { 1 } else { 0 }));
    let count = m.range((8, 16)..=(8, 16)).count();
    out.push_str(&format!("{}\n", count));
    out.push_str(&format!("{}\n", m.get(&(100, 200)).map(|s| s.as_str()).unwrap_or("default")));
    m.clear();
    out.push_str(&format!("{}\n", m.len()));
    out.push_str(&format!("{}\n", if m.is_empty() { 1 } else { 0 }));
    print!("{}", out);
}
EOF
