// Pure closed-form generator: no map at all. Proves the line map.
fn c_atoi(s: &str) -> i32 {
    let b = s.as_bytes(); let mut i = 0usize;
    while i < b.len() && (b[i] == b' ' || (b[i] >= 0x09 && b[i] <= 0x0d)) { i += 1; }
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') { neg = b[i] == b'-'; i += 1; }
    let mut acc: i64 = 0; let mut sat = false;
    while i < b.len() && b[i].is_ascii_digit() {
        if !sat { acc = acc * 10 + (b[i] - b'0') as i64; if acc > i64::MAX / 16 { sat = true; } }
        i += 1;
    }
    let v: i64 = if sat { if neg { i64::MIN } else { i64::MAX } } else if neg { -acc } else { acc };
    v as i32
}
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: i64 = if args.len() > 1 { c_atoi(&args[1]) as i64 } else { 18 };
    let nn = if n > 0 { n } else { 0 };            // N = number of initial keys
    let mm = if n / 2 > 0 { n / 2 } else { 0 };    // M = |m2|
    let mut o = String::new();
    o.push_str(&format!("{}\n", nn));                                     // 1 size
    o.push_str(&format!("{}\n", (nn >= 4) as i32));                       // 2 contains(3,6)
    o.push_str(&format!("{}\n", (nn >= 6) as i32));                       // 3 contains(5,10)
    o.push_str(&format!("{}\n", if nn >= 4 { "value_3" } else { "" }));   // 4 m[k1]
    o.push_str("modified\n");                                             // 5
    let after_sub = if nn >= 4 { nn } else { nn + 1 };
    o.push_str(&format!("{}\n", after_sub));                              // 6 keys.size
    o.push_str(&format!("{}\n", after_sub));                              // 7 values.size
    let a = if nn >= 4 { nn - 4 } else { 0 };                             // |A|, A={4..N-1}
    o.push_str(&format!("{}\n", a));                                      // 8 size after erase
    if nn >= 7 { o.push_str("value_6\n"); }                               // 9  find
    if nn >= 8 { o.push_str("7\n"); }                                     // 10 lower_bound
    if nn >= 9 { o.push_str("8\n"); }                                     // 11 upper_bound
    let hi = std::cmp::min(nn - 1, 9 + mm);
    let overlap = std::cmp::max(0, hi - 9);
    o.push_str(&format!("{}\n", a + mm - overlap));                       // 12 size after update
    o.push_str(&format!("{}\n", (nn >= 13 || mm >= 3) as i32));           // 13 contains(12,24)
    o.push_str(&format!("{}\n", (nn >= 9) as i32));                       // 14 equal_range count
    o.push_str(&format!("{}\n", if mm >= 91 { "other_90" }
                                else if nn >= 101 { "value_100" }
                                else { "default" }));                     // 15 get
    o.push_str("0\n");                                                    // 16 size after clear
    o.push_str("1\n");                                                    // 17 empty
    print!("{}", o);
}
EOF
