fn c_atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0usize;
    while i < b.len() && (b[i] == b' ' || (0x09..=0x0d).contains(&b[i])) { i += 1; }
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') { neg = b[i] == b'-'; i += 1; }
    let mut acc: i64 = 0;
    let mut sat = false;
    while i < b.len() && b[i].is_ascii_digit() {
        let d = (b[i] - b'0') as i64;
        if !sat {
            // strtol accumulates negatives to avoid asymmetry; emulate with checked ops.
            match acc.checked_mul(10).and_then(|x| if neg { x.checked_sub(d) } else { x.checked_add(d) }) {
                Some(v) => acc = v,
                None => { sat = true; acc = if neg { i64::MIN } else { i64::MAX }; }
            }
        }
        i += 1;
    }
    let _ = sat;
    acc as i32   // (int)strtol(...): wrapping truncation
}
EOF
